<?php
namespace App\Services\Communications;
use App\Support\Database;use App\Support\TenantContext;use App\Support\Auth;
final class CommunicationService { public function queue(int $clientId,string $channel,string $body,?string $subject=null,?int $clientServiceId=null,?string $scheduledAt=null):int{$s=Database::pdo()->prepare('INSERT INTO communications(tenant_id,client_id,client_service_id,channel,direction,subject,status,body,scheduled_at,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,NOW())');$s->execute([TenantContext::id(),$clientId,$clientServiceId,$channel,'outbound',$subject,'queued',$body,$scheduledAt,Auth::id()]);return (int)Database::pdo()->lastInsertId();} public function send(int $id):array{$s=Database::pdo()->prepare('SELECT * FROM communications WHERE tenant_id=? AND id=?');$s->execute([TenantContext::id(),$id]);$m=$s->fetch();if(!$m)return ['status'=>'missing'];$channel=match($m['channel']){'email'=>new EmailChannel(),'sms'=>new SMSChannel(),'whatsapp'=>new WhatsAppChannel(),'voice'=>new VoiceChannel(),default=>new NullChannel()};$result=$channel->send($m);$u=Database::pdo()->prepare('UPDATE communications SET status=?,provider=?,sent_at=IF(?=\'sent\',NOW(),sent_at) WHERE id=?');$u->execute([$result['status'],$result['provider'],$result['status'],$id]);return $result;}}
